(12, 'PEMILU OSIS', 'pemilu-osis-1791346508', 'Bismillah, \r\nRangkaian kegiatan OSIS, mulai dari Debat, Pemilu, Musyawarah Besar dan SERTIJAB Pengurus Baru', 'SMP IT Madani', '2026-10-23 00:00:00', 'ongoing', '/uploads/agenda/whatsapp-image-2026-10-06-at-082425-1791346508-helys.webp', '/uploads/agenda/whatsapp-image-2026-10-06-at-082425-1791346508-7eHxO.jpeg', '2026-10-07 04:15:08', '2026-10-23 00:10:00'),
(13, 'SHAUM SUNNAH OKTOBER', 'shaum-sunnah-oktober-1792714138', 'Bismillah,\r\n\r\nMari bersama menambah amalan di dunia dengan menjalankan sunnah-sunnahNya.. \r\ndianjurkan bagi seluruh civitas SMP IT Madani untuk berpuasa senin nanti.. pada hari itu kantin akan ditutup dan tidak disediakan makanan, makanan akan dibungkus untuk dibawa pulang.. \r\nsyukron, Barakallahu fiikum..', 'SMP IT Madani', '2026-10-26 00:00:00', 'upcoming', '/uploads/agenda/shaum-sunnah-oktober-2026-poster-1792714137-6NK6I.webp', '/uploads/agenda/shaum-sunnah-oktober-2026-poster-1792714138-lDNO0.png', '2026-10-23 00:08:58', '2026-10-23 00:27:39');
INSERT INTO `anggota_dewans` (`id`, `name`, `slug`, `position`, `fraction`, `profile_summary`, `education`, `photo`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Ribang Imam Satria, S.Pi., Gr.', 'ribang-imam-satria-spi-gr', 'Kepala Sekolah', 'Pimpinan Sekolah', 'Kepala SMPS IT Madani Kayuagung. Berkomitmen mewujudkan generasi Qur\'ani yang berakhlak mulia, berprestasi dalam sains dan teknologi, mandiri, serta berwawasan global di bawah naungan JSIT Indonesia.', 'S1 Ilmu Administrasi Negara, Universitas Sriwijaya; S2 Manajemen Pendidikan, Universitas PGRI; Gr (Pendidikan Profesi Guru)', '/uploads/dewan/kepala-sekolah.webp', 1, '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(2, 'Amaliah, M.Pd.,Gr', 'ustadz-fulan-spd', 'Waka Kesiswaan & Pembina PMR', 'Guru Ilmu Pengetahuan Sosial', '<p style=\"text-align: justify;\"><strong>Amaliah, M.Pd., Gr. </strong>merupakan pendidik di <strong>SMPS IT Madani Kayuagung</strong> yang memiliki komitmen dalam mendampingi peserta didik untuk berkembang secara akademik, sosial, dan karakter. Saat ini beliau dipercaya mengemban amanah sebagai <strong>Wakil Kepala Sekolah Bidang Kesiswaan</strong> serta berperan dalam pembinaan <strong>Palang Merah Remaja (PMR)</strong>.</p><p style=\"text-align: justify;\">Dalam kegiatan pembelajaran, Amaliah, M.Pd., Gr. mengampu <strong>Mata Pelajaran Ilmu Pengetahuan Sosial (IPS)</strong>. Melalui pembelajaran IPS, beliau berupaya mengajak peserta didik memahami berbagai fenomena sosial, lingkungan, budaya dan kehidupan bermasyarakat secara kritis serta kontekstual.</p><p style=\"text-align: justify;\">Beliau menempuh pendidikan hingga jenjang <strong>Magister (S2) Manajemen Pendidikan</strong>, yang memperkuat kompetensi dalam bidang pengelolaan pendidikan, kepemimpinan dan pengembangan peserta didik. Dengan latar belakang akademik tersebut, beliau turut berkontribusi dalam menciptakan lingkungan sekolah yang tertib, aktif, positif, dan mendukung tumbuhnya potensi peserta didik.</p><p style=\"text-align: justify;\">Sebagai pendidik sekaligus pengelola bidang kesiswaan, Amaliah, M.Pd., Gr. berkomitmen untuk membangun budaya sekolah yang mendorong peserta didik menjadi pribadi yang <strong>berkarakter, bertanggung jawab, peduli terhadap sesama, serta mampu berperan aktif di lingkungan sekolah dan masyarakat</strong>.</p>', 'S2 Management Pendidikan', '/uploads/dewan/1000612915-1792405596-pxq84.webp', 2, '2026-09-20 05:59:18', '2026-10-19 10:26:37'),
(3, 'Abdul Qodir Jaelani, S.Pd.I.,Gr', 'ustadzah-fulanah-spdi', 'PJ. Sarpras dan Wali Kelas IX', 'Guru Pendidikan Agama Islam dan Budi Pekerti', '<p>Pengampu mata pelajaran Pendidikan Agama Islam dan Budi Pekerti</p>', 'S1 Pendidikan Agama Islam', '/uploads/dewan/avatar-default.svg', 3, '2026-09-20 05:59:18', '2026-09-29 03:10:59'),
(4, 'Okta Riyandini, S.Pd.I.,M.Pd.,Gr', 'ustadz-fulan-skom', 'PJ. Media dan Wali Kelas IX', 'Guru Tahsin Tahfizh Qur\'an', '<p>Selain mengampu sebagai PJ. Media</p>', 'S2 Pendidikan Agama Islam', '/uploads/dewan/avatar-default.svg', 4, '2026-09-20 05:59:18', '2026-09-29 03:15:33'),
(5, 'Wike Sutasih, S.Pd., Gr', 'ustadzah-fulanah-spd', 'PJ. BK Bintun, Pembina OSIS dan Wali Kelas VII', 'Ilmu Pengetahuan Sosial dan Seni Budaya', '<p>Pengampu mata pelajaran Bahasa Inggris aktif dan pembina kegiatan English Club, storytelling, dan literasi bahasa siswa.</p>', 'S1 Ekonomi', '/uploads/dewan/avatar-default.svg', 5, '2026-09-20 05:59:18', '2026-09-29 03:12:08'),
(6, 'Kamrin, S.Pd., Gr', 'ustadz-fulan-sor', 'Pembina Pramuka Putra dan Wali Kelas VIII', 'Guru PJOK', '<p>Guru Pendidikan Jasmani, Olahraga, dan Kesehatan, aktif membina kedisiplinan, kepanduan Pramuka SIT, dan kebugaran jasmani siswa.</p>', 'S1 Pendidikan Olahraga', '/uploads/dewan/avatar-default.svg', 6, '2026-09-20 05:59:18', '2026-09-29 03:29:19'),
(7, 'Endang Sriwahyuni, S.Si. Gr', 'ustadzah-fulanah-ssi', 'Pembina Pramuka Putri dan Wali Kelas IX', 'Guru Ilmu Pengetahuan Alam', '<p>Pembina Pramuka Putri</p>', 'S1 Biologi', '/uploads/dewan/avatar-default.svg', 7, '2026-09-20 05:59:18', '2026-09-29 03:29:01'),
(8, 'Robin Saputra, S.Pd.,Gr', 'robin-saputra-spdgr', 'PJ. K5 dan Wali Kelas VII', 'Ilmu Pengetahuan Sosial dan Pendidikan Kewarganegaraan', '<p><br></p>', 'S1 Sejarah', '/uploads/logo-madani-square.png', 8, '2026-09-29 02:49:55', '2026-09-29 03:29:40'),
(9, 'Ensi, M.Pd', 'ensy-mpd', 'PJ. Literasi dan Wali Kelas VIII', 'Guru Bahasa Arab', '<p><br></p>', 'S2 Pendidikan Agama Islam', '/uploads/logo-madani-square.png', 9, '2026-09-29 02:52:53', '2026-09-29 03:29:59'),
(10, 'Halimatun Alawiyah', 'halimatun-alawiyah', 'PJ. Tahsin Tahfizh Qur\'an', 'Guru Tahsin Tafizh Qur\'an', '<p><br></p>', '', '/uploads/logo-madani-square.png', 10, '2026-09-29 02:54:25', '2026-09-29 02:54:25'),
