INSERT INTO `bidangs` (`id`, `name`, `slug`, `description`, `address`, `phone`, `email`, `website`, `icon`, `thumbnail`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Ruang Kelas Nyaman & Multimedia', 'ruang-kelas-nyaman-dan-multimedia', '<p>Ruang kelas representatif yang bersih, dilengkapi proyektor LCD, CCTV, Sound Bel dan tata letak ergonomis untuk memaksimalkan fokus belajar.</p>', '', '', '', NULL, 'fa-solid fa-chalkboard-user', '/uploads/fasilitas/fasilitas-ruang-kelas.webp', 1, '2026-09-20 05:59:18', '2026-10-02 10:25:29'),
(2, 'Perpustakaan & Pojok Literasi Digital', 'perpustakaan-dan-pojok-literasi-digital', 'Koleksi lengkap buku teks pelajaran, referensi ensiklopedia Islam, sastra ilmiah, komputer literasi digital, dan sudut baca nyaman untuk menumbuhkan gemar membaca.', 'Kampus SMPS IT Madani Kayuagung', '0858-3817-3417', 'smpsislamterpadumadani@gmail.com', NULL, 'fa-solid fa-book-open', '/uploads/fasilitas/fasilitas-perpustakaan.webp', 2, '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(3, 'Laboratorium IPA & Sains Terpadu', 'laboratorium-ipa-sains-terpadu', 'Fasilitas laboratorium lengkap untuk eksperimen biologi, fisika, dan kimia dasar, mendukung pembelajaran praktikum dan kelas olimpiade sains.', 'Kampus SMPS IT Madani Kayuagung', '0858-3817-3417', 'smpsislamterpadumadani@gmail.com', NULL, 'fa-solid fa-flask-vial', '/uploads/fasilitas/fasilitas-lab-ipa.webp', 3, '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(4, 'Masjid & Pusat Ibadah Kampus Madani', 'masjid-dan-pusat-ibadah', 'Masjid kampus yang asri sebagai pusat ibadah sholat berjamaah, sholat dhuha, tadarus Al-Qur\'an, dan halaqah tahfidz siswa.', 'Kampus SMPS IT Madani Kayuagung', '0858-3817-3417', 'smpsislamterpadumadani@gmail.com', NULL, 'fa-solid fa-mosque', '/uploads/fasilitas/fasilitas-masjid.webp', 4, '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(5, 'Lapangan Olahraga & Area Outbound', 'lapangan-olahraga-dan-outbound', 'Lapangan olahraga serbaguna untuk futsal, basket, voli, bulutangkis, serta arena latihan panahan (archery) dan kepanduan Pramuka SIT.', 'Kampus SMPS IT Madani Kayuagung', '0858-3817-3417', 'smpsislamterpadumadani@gmail.com', NULL, 'fa-solid fa-volleyball', '/uploads/fasilitas/fasilitas-lapangan.webp', 5, '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(6, 'Gedung Kampus Terpadu', 'gedung-kampus-terpadu', 'Kompleks gedung sekolah yang asri, aman, dan berpagar penuh dengan pos satpam 24 jam serta taman hijau yang mendukung kenyamanan belajar.', 'Kampus SMPS IT Madani Kayuagung', '0858-3817-3417', 'smpsislamterpadumadani@gmail.com', NULL, 'fa-solid fa-school', '/uploads/fasilitas/fasilitas-gedung-utama.webp', 6, '2026-09-20 05:59:18', '2026-09-20 05:59:18');
