INSERT INTO `downloads` (`id`, `title`, `description`, `category_type`, `file_path`, `cover_image`, `file_type`, `file_size`, `download_count`, `created_at`, `updated_at`) VALUES
(1, 'Panduan Kurikulum Tahfidz Al-Qur\'an 2 Juz SMPS IT Madani', 'Modul resmi kurikulum tahfidz mutqin SMPS IT Madani Kayuagung berbasis standar JSIT Indonesia.', 'E-Book', '/uploads/downloads/panduan-mutqin-tahfidz-madani.pdf', '/uploads/covers/cover-tahfidz-mutqin.webp', 'PDF', '9.0 KB', 359, '2026-09-20 05:59:18', '2026-10-26 06:48:31'),
(2, 'Buku Saku Adab & 10 Karakter (Muwashofat) Siswa JSIT', 'Pedoman pembiasaan akhlak islami, adab kepada guru dan orang tua, tata tertib siswa asrama dan sekolah.', 'E-Book', '/uploads/downloads/buku-saku-adab-karakter-siswa.pdf', '/uploads/covers/cover-karakter-siswa.webp', 'PDF', '6.9 KB', 296, '2026-09-20 05:59:18', '2026-10-28 15:50:30'),
(3, 'Petunjuk Praktikum Laboratorium IPA Terpadu SMPS IT Madani', 'Pedoman eksperimen laboratorium biologi dan fisika untuk siswa kelas VII-IX SMPS IT Madani.', 'E-Book', '/uploads/downloads/petunjuk-praktikum-sains-terpadu.pdf', '/uploads/covers/cover-praktikum-sains.webp', 'PDF', '6.6 KB', 210, '2026-09-20 05:59:18', '2026-10-26 04:53:45'),
(4, 'Kurikulum Pembinaan Da\'i Muda, Khitabah & Public Speaking', 'Kumpulan materi public speaking, retorika dakwah 3 bahasa (Indonesia, Arab, Inggris), dan sistematika kultum.', 'E-Book', '/uploads/downloads/kurikulum-pembinaan-dai-muda.pdf', '/uploads/covers/cover-dai-muda.webp', 'PDF', '6.5 KB', 223, '2026-09-20 05:59:18', '2026-10-26 10:25:10'),
(5, 'Buku Saku Kosakata Harian Bilingual Bahasa Arab & Inggris Siswa', 'Modul percakapan bilingual harian asrama dan lingkungan sekolah untuk mempercepat penguasaan active speaking.', 'E-Book', '/uploads/downloads/buku-saku-kosakata-bilingual.pdf', '/uploads/covers/cover-bilingual-arab-inggris.webp', 'PDF', '6.6 KB', 327, '2026-09-20 05:59:18', '2026-10-26 13:59:24'),
(6, 'Panduan Sukses Asesmen Nasional & Masuk Sekolah Lanjutan Unggulan Favorit', 'Strategi sukses menembus sekolah lanjutan favorit impian, pembedahan materi literasi dan numerasi Asesmen Nasional.', 'E-Book', '/uploads/downloads/panduan-sukses-snbt-ptn.pdf', '/uploads/covers/cover-sukses-snbt.webp', 'PDF', '6.6 KB', 472, '2026-09-20 05:59:18', '2026-10-30 05:01:13'),
(7, 'Logo Resmi SMPS IT Madani Kayuagung (High Resolution)', 'File logo resmi SMPS IT Madani Kayuagung format PNG transparan.', 'Logo', '/uploads/logo-madani.png', NULL, 'PNG', '120 KB', 802, '2026-09-20 05:59:18', '2026-11-01 08:34:19'),
(8, 'Logo Lambang Madani Square HD', 'Logo lambang persegi SMPS IT Madani Kayuagung format PNG.', 'Logo', '/uploads/logo-madani-square.png', NULL, 'PNG', '85 KB', 339, '2026-09-20 05:59:18', '2026-10-31 22:59:39');
INSERT INTO `dpcs` (`id`, `name`, `slug`, `description`, `head_name`, `address`, `thumbnail`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Program Tahsin Tahfidz Quran', 'program-tahfidz-2-juz-mutqin', '<p>Bimbingan intensif membaca Al-Qur\'an dengan tartil, tahsin bersanad, dan hafalan mutqin minimal 2 juz.</p>', 'Ustadzah Halimatun Alawiyah', 'Kurikulum JSIT', '/uploads/dpc/whatsapp-image-2026-09-29-at-094827-1790920775-fX8ut.webp', 1, '2026-09-20 05:59:18', '2026-10-02 05:59:36'),
(2, 'Bina Pribadi Islam (BPI) & Karakter Islami', 'bina-pribadi-islam-bpi', '<p>Halaqah pekanan pembinaan adab, pembiasaan ibadah yaumiyah, dzikir ma\'tsurat, serta penanaman akhlaqul karimah.</p>', 'Ustadzah Leti Asni', 'Kurikulum JSIT', '/uploads/dpc/whatsapp-image-2026-09-04-at-092329-1790920915-tKuSe.webp', 2, '2026-09-20 05:59:18', '2026-10-02 06:01:55'),
(3, 'Ekstrakurikuler PRAMUKA', 'kurikulum-terpadu-jsit-merdeka', '<p>Pramuka SAKO JSIT, setiap hari kamis dari pukul 09.45-11.45 wib (3 JP)</p>', 'Ustadz Kamrin dan Ustadzah Endang Sriwahyuni', 'Kurikulum JSIT', '/uploads/dpc/whatsapp-image-2026-10-01-at-114936-1790921240-zmImM.webp', 3, '2026-09-20 05:59:18', '2026-10-02 06:07:20'),
(4, 'IU CARE', 'belajar-bersama-maestro-riset', '<p>Eksplorasi empati dan kepedulian antar sesama. Belajar budgeting, mengkonsep kegiatan dan menghandel kegiatan.</p>', 'Ustadz Abdul Qodir Jaelani', 'Project Kokurikuler', '/uploads/dpc/whatsapp-image-2026-10-02-at-131001-1790921503-hyjsd.webp', 4, '2026-09-20 05:59:18', '2026-10-02 06:11:43'),
(5, 'IU Safar & Outing Class Edukatif', 'iu-safar-outing-class', 'Pembelajaran luar kelas berbasis observasi alam, studi kampus, renang, dan rekreasi edukatif untuk memperluas cakrawala siswa.', NULL, 'Outdoor Learning & Wawasan', NULL, 5, '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(6, 'IU Berkhidmat (Bakti Sosial Masyarakat)', 'iu-berkhidmat-bakti-sosial', 'Kiprah nyata siswa dalam melayani dan memberikan kontribusi positif bagi masyarakat di Kabupaten Ogan Komering Ilir (Kayuagung).', NULL, 'Kepedulian Sosial & Dakwah', NULL, 6, '2026-09-20 05:59:18', '2026-09-20 05:59:18');
