INSERT INTO `ppdb_tracks` (`id`, `name`, `slug`, `percentage`, `quota_percentage`, `discount_info`, `description`, `requirements`, `order_index`, `is_active`, `created_at`, `updated_at`, `quota`, `cashback_info`, `order`) VALUES
(1, 'Jalur First Brave', 'jalur-first-brive', '10%', 0, NULL, 'Cashback Rp. 500.000 Uang Bangunan, Free Pendaftaran serta MERCHANDISE EXCLUSIVE\r\nJika membayar 50% Dana Pangkal cashback Rp. 300.000,-\r\ndan Jika Melunasi 100% Dana Pangkal Cashback Rp. 600.000,-', NULL, 0, 1, '2026-09-20 05:59:18', '2026-10-14 04:04:50', 'Hanya 20 Siswa', 'Cashback Khusus Pendaftar Gelombang Pertama', 1),
(2, 'Jalur Mutasi Kerja', 'jalur-mutasi-kerja', '5%', 0, NULL, 'Jalur khusus bagi putra-putri dari orang tua yang mengalami mutasi kerja atau pindah tugas kedinasan (TNI, Polri, ASN, BUMN, Perusahaan Swasta) ke wilayah Kabupaten Ogan Komering Ilir (Kayuagung) dan sekitarnya.', NULL, 0, 1, '2026-09-20 05:59:18', '2026-09-20 10:36:03', 'Hanya 10 Siswa', 'Keringanan Khusus Pindahan Kedinasan / Perusahaan', 2),
(3, 'Jalur Tahfidz', 'jalur-tahfidz', '5%', 0, NULL, 'Tahfidz minimal 2-3 Juz Cashback Rp. 500.000,-\r\nTahfidz minimal 4-5 Juz Cashback Rp. 750.000,-\r\nTahfidz >5 Juz Cashback Rp. 1.000.000,-\r\nMengikuti tes sima\'an tahfidz bersama dewan musyrif Al-Qur\'an Madani.', NULL, 0, 1, '2026-09-20 05:59:18', '2026-09-20 10:36:59', 'Hanya 10 Siswa', 'Cashback Rp 750.000,- s/d Rp 1.000.000,-', 3),
(4, 'Jalur Alumni', 'jalur-alumni', '25%', 0, NULL, 'Keringanan istimewa bagi lulusan SD IT Madani dan SD IT Madani Kayuagung 2 yang melanjutkan ke SMPS IT Madani Kayuagung berupa potongan biaya uang pangkal sebesar Rp. 1.000.000,- dengan kuota (hanya 50 siswa).', NULL, 0, 1, '2026-09-20 05:59:18', '2026-09-20 05:59:18', 'Hanya 50 Siswa', 'Potongan Uang Pangkal Rp 1.000.000,-', 4),
(5, 'Jalur Prestasi', 'jalur-prestasi', '30%', 0, NULL, 'Prestasi Akademik maupun Non Akademik\r\nJuara 1 Tingkat Kota Cashback Rp. 500.000,-\r\nJuara 1 Tingkat Provinsi Cashback Rp. 750.000,-', NULL, 0, 1, '2026-09-20 05:59:18', '2026-09-20 10:39:17', 'Prioritas Penerimaan 60 Siswa', 'Cashback Rp. 500.000- Rp. 750.000,-', 5),
(6, 'Jalur Reguler', 'jalur-reguler', '25%', 0, NULL, 'Jalur seleksi reguler melalui tahapan:\r\nTes Potensi Akademik (Matematika, Bahasa Indonesia, PAI, Bahasa Inggris).\r\nTes Kemampuan Membaca Al-Qur\'an (Tahsin & Tajwid).\r\nWawancara Komitmen Orang Tua & Siswa.', NULL, 0, 1, '2026-09-20 05:59:18', '2026-09-20 10:39:48', 'Hanya 50 Siswa', 'Tes Mandiri Sekolah', 6);
