xx\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"mother_name\",\n        \"label\": \"Nama Lengkap Ibu \\/ Wali\",\n        \"section\": \"ibu\",\n        \"type\": \"text\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Nama lengkap ibu\\/wali...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"mother_birth_place\",\n        \"label\": \"Tempat Lahir Ibu\",\n        \"section\": \"ibu\",\n        \"type\": \"text\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Kota kelahiran ibu...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"mother_birth_date\",\n        \"label\": \"Tanggal Lahir Ibu\",\n        \"section\": \"ibu\",\n        \"type\": \"date\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"mother_address\",\n        \"label\": \"Alamat Ibu \\/ Wali\",\n        \"section\": \"ibu\",\n        \"type\": \"textarea\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Alamat domisili ibu\\/wali...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"mother_education\",\n        \"label\": \"Pendidikan Terakhir Ibu\",\n        \"section\": \"ibu\",\n        \"type\": \"select\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [\n            \"Tidak Sekolah\",\n            \"SD \\/ Sederajat\",\n            \"SMP \\/ Sederajat\",\n            \"SMA \\/ SMK \\/ MA\",\n            \"Diploma (D1\\/D2\\/D3)\",\n            \"Sarjana (S1)\",\n            \"Magister (S2)\",\n            \"Doktor (S3)\"\n        ],\n        \"placeholder\": \"Pilih Pendidikan...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"mother_job\",\n        \"