INSERT INTO `testimonials` (`id`, `name`, `profession`, `content`, `photo`, `status`, `created_at`, `updated_at`) VALUES
(1, 'H. Bambang Irawan, S.E', 'Wali Murid Kelas VIII', 'Alhamdulillah, semenjak bersekolah di SMP IT Madani Kayuagung, perkembangan ibadah dan akhlak anak saya meningkat drastis. Sholat 5 waktu tertib dan hafalannya terus bertambah mutqin.', '/uploads/testimoni/wali-siswa-1.webp', 'publish', '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(2, 'Dra. Hj. Nuraini', 'Wali Murid Kelas IX', 'Sekolah Islam Terpadu terbaik di Kayuagung. Para ustaz dan ustazah membimbing anak-anak dengan penuh kasih sayang. Program bilingual dan pembiasaan adabnya sangat terasa manfaatnya.', '/uploads/testimoni/wali-siswa-2.webp', 'publish', '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(3, 'Fathir Rahman', 'Alumni SIT Madani', 'Tiga tahun belajar di SMP IT Madani memberikan fondasi yang sangat kokoh bagi saya, baik dalam hafalan Qur\'an, kemampuan sains, maupun kepemimpinan di jenjang pendidikan berikutnya.', '/uploads/testimoni/alumni-1.webp', 'publish', '2026-09-20 05:59:18', '2026-09-20 05:59:18');
