INSERT INTO `videos` (`id`, `title`, `slug`, `youtube_url`, `youtube_id`, `description`, `created_at`, `updated_at`) VALUES
(1, 'Mengenal Lebih Dekat Profil dan Visi SMP IT Madani Kayuagung', 'mengenal-lebih-dekat-profil-dan-visi-smp-it-sit-madani-prabumulih', 'https://www.youtube.com/watch?v=_ltiwpOmK1k', '_ltiwpOmK1k', 'Mengenal lebih dekat profil resmi SMPS IT Madani Kayuagung: visi kelembagaan, sarana prasarana terpadu, dan pembinaan karakter generasi Qur\'ani.', '2026-09-20 05:59:18', '2026-09-20 05:59:18'),
(2, 'Budayakan 5S ~ Senyum Sapa Salam Sopan & Santun | SMPS IT Madani Kayuagung', 'budayakan-5s-senyum-sapa-salam-sopan-santun', 'https://www.youtube.com/watch?v=sBS7nP9bb1Q', 'sBS7nP9bb1Q', 'Penanaman adab dan akhlak mulia melalui pembiasaan budaya 5S (Senyum, Sapa, Salam, Sopan, dan Santun) dalam keseharian siswa dan civitas akademika.', '2026-09-20 05:54:18', '2026-09-20 05:54:18'),
(3, 'Tutorial Penggunaan Alat Pemadam Api Ringan (APAR) Bersama BPBD Kabupaten Ogan Komering Ilir (Kayuagung)', 'tutorial-penggunaan-alat-pemadam-api-ringan-apar-bpbd', 'https://www.youtube.com/watch?v=_Bide_e-eCw', '_Bide_e-eCw', 'Edukasi tanggap darurat dan pelatihan praktis pemadaman api menggunakan APAR bekerja sama dengan Badan Penanggulangan Bencana Daerah (BPBD) Kabupaten Ogan Komering Ilir (Kayuagung).', '2026-09-20 05:49:18', '2026-09-20 05:49:18'),
(4, 'Jambore Daerah Sumsel IX Tahun 2026 | SMP IT Madani Kayuagung', 'jambore-daerah-sumsel-ix-tahun-2026', 'https://www.youtube.com/watch?v=v5DIIOd7_94', 'v5DIIOd7_94', 'Dokumentasi kontingen kepanduan Pramuka SIT SMPS IT Madani Kayuagung dalam ajang bergengsi Jambore Daerah Sumatera Selatan IX.', '2026-09-20 05:44:18', '2026-09-20 05:44:18'),
(5, 'Tilawah Al-Qur\'an Siswa | Syazani Jalil Gumilar', 'tilawah-al-quran-siswa-syazani-jalil-gumilar', 'https://www.youtube.com/watch?v=tQhpl36L_h0', 'tQhpl36L_h0', 'Lantunan ayat suci Al-Qur\'an tartil dan merdu yang dibawakan oleh siswa SMPS IT Madani Kayuagung.', '2026-09-20 05:39:18', '2026-09-20 05:39:18'),
(6, 'Praktik Manasik Haji SMP IT Madani Kayuagung', 'praktik-manasik-haji-smp-it-sit-madani-prabumulih', 'https://www.youtube.com/watch?v=3BwYjZrjzfQ', '3BwYjZrjzfQ', 'Pembelajaran langsung fiqih ibadah haji dan umrah melalui simulasi manasik haji terpadu di lingkungan sekolah.', '2026-09-20 05:34:18', '2026-09-20 05:34:18'),
(7, 'Pentas Seni | Tari Kreasi - Sanggar Ceria SMP IT Madani Kayuagung', 'pentas-seni-tari-kreasi-sanggar-ceria', 'https://www.youtube.com/watch?v=XZSRif9HjNE', 'XZSRif9HjNE', 'Kreativitas seni pertunjukan dan tari kreasi nusantara islami oleh Sanggar Ceria siswi SMPS IT Madani.', '2026-09-20 05:29:18', '2026-09-20 05:29:18'),
(8, 'Nonton Bareng Edukatif | Children of Heaven ~ SMP IT Madani Kayuagung', 'nonton-bareng-edukatif-children-of-heaven', 'https://www.youtube.com/watch?v=M3JI1sI7VGA', 'M3JI1sI7VGA', 'Apresiasi karya sinema edukatif Children of Heaven untuk menumbuhkan nilai empati, kesederhanaan, dan cinta keluarga bagi siswa.', '2026-09-20 05:24:18', '2026-09-20 05:24:18'),
(9, 'ISHOMA ~ Isi Hari Obrolan Makna | Aninda Izzati', 'ishoma-isi-hari-obrolan-makna-aninda-izzati', 'https://www.youtube.com/watch?v=q18kFzeWhjk', 'q18kFzeWhjk', 'Program bincang santai dan inspiratif siswa ISHOMA (Isi Hari Obrolan Makna) seputar motivasi belajar dan prestasi generasi muda.', '2026-09-20 05:19:18', '2026-09-20 05:19:18'),
(10, 'Tips Hafalan Qur\'an: Kunci Kelancaran Muroja\'ah', 'tips-hafalan-quran-kunci-kelancaran-murojaah', 'https://www.youtube.com/watch?v=La-a0-J64HE', 'La-a0-J64HE', 'Kiat sukses dan motivasi menjaga kelancaran hafalan Al-Qur\'an melalui istiqomah muroja\'ah harian bersama asatidz pembimbing.', '2026-09-20 05:14:18', '2026-09-20 05:14:18'),
(11, 'Dokumentasi Ceria Siswa & Guru SMPS IT Madani', 'dokumentasi-ceria-siswa-guru-smps-it-sit-madani', 'https://www.youtube.com/watch?v=LS9Cc0lHbBY', 'LS9Cc0lHbBY', 'Potret kekeluargaan, kehangatan ukhuwah, dan kebersamaan guru dan siswa dalam berbagai momen bermakna di sekolah.', '2026-09-20 05:09:18', '2026-09-20 05:09:18'),
(12, 'SUPERVISI AKADEMIK SEMESTER GANJIL TP. 26/27', 'supervisi-akademik-semester-ganjil-tp-2627-1791362622', 'https://www.youtube.com/watch?v=aSZ_RzSsq6U', 'aSZ_RzSsq6U', '', '2026-10-07 08:43:42', '2026-10-07 08:43:42'),
(20, 'BTD', 'btd-1792052336', 'https://www.youtube.com/watch?v=DLw-bQ_T3ZA', 'DLw-bQ_T3ZA', '', '2026-10-15 08:18:56', '2026-10-15 08:18:56');
